1	import React, { useState, useEffect, useCallback } from 'react';
2	import { useNavigate } from 'react-router-dom';
3	import { motion, AnimatePresence } from 'framer-motion';
4	import { getTags, criarTag, atualizarTag, removerTag } from '../../services/adminService';
5	import { useAuth } from '../../contexts/AuthContext';
6	import { ThemeToggle } from '../../contexts/ThemeContext';
7	import Icon from '../../components/AppIcon';
8	
9	const AdminNav = ({ active }) => {
10	  const navigate = useNavigate();
11	  const { signOut } = useAuth();
12	  const links = [
13	    { label: 'Dashboard',    path: '/admin' },
14	    { label: 'Empresas',     path: '/admin/empresas' },
15	    { label: 'Categorias',   path: '/admin/categorias' },
16	    { label: 'Tipos',        path: '/admin/tipos-estabelecimento' },
17	    { label: 'Tags',         path: '/admin/tags' },
18	    { label: 'Comissões',    path: '/admin/comissoes' },
19	    { label: 'Configurações',path: '/admin/configuracoes' },
20	  ];
21	  return (
22	    <nav className="flex gap-1.5 flex-wrap items-center">
23	      {links.map((l) => (
24	        <button key={l.path} onClick={() => navigate(l.path)}
25	          className={`px-3 py-2 text-sm font-semibold rounded-lg transition-colors ${
26	            active === l.path
27	              ? 'text-white bg-blue-600 shadow-sm'
28	              : 'text-gray-700 dark:text-zinc-300 hover:bg-gray-100 dark:hover:bg-zinc-800'
29	          }`}>
30	          {l.label}
31	        </button>
32	      ))}
33	      <button onClick={async () => { await signOut(); navigate('/customer-registration-login'); }}
34	        className="px-3 py-2 text-sm font-semibold text-red-600 dark:text-red-400 hover:bg-red-50 dark:hover:bg-red-950/40 rounded-lg border border-red-200 dark:border-red-900">
35	        Sair
36	      </button>
37	      <ThemeToggle inline />
38	    </nav>
39	  );
40	};
41	
42	const slugify = (text) =>
43	  text.toLowerCase().trim()
44	    .normalize('NFD').replace(/[̀-ͯ]/g, '')
45	    .replace(/[^a-z0-9]+/g, '_')
46	    .replace(/^_|_$/g, '');
47	
48	const EMPTY = { name: '', slug: '', descricao: '', is_auto: false, ordem: 0, ativo: true };
49	
50	const Modal = ({ tag, onClose, onSave }) => {
51	  const [form, setForm] = useState(
52	    tag
53	      ? { name: tag.name, slug: tag.slug, descricao: tag.descricao ?? '', is_auto: tag.is_auto, ordem: tag.ordem, ativo: tag.ativo }
54	      : { ...EMPTY }
55	  );
56	  const [salvando, setSalvando] = useState(false);
57	  const [erro, setErro] = useState(null);
58	  const isEdicao = !!tag;
59	
60	  const set = (k, v) => setForm((f) => {
61	    const next = { ...f, [k]: v };
62	    // Auto-preenche slug ao digitar nome (só criação)
63	    if (k === 'name' && !isEdicao) next.slug = slugify(v);
64	    return next;
65	  });
66	
67	  const handleSubmit = async (e) => {
68	    e.preventDefault();
69	    if (!form.name.trim() || !form.slug.trim()) return;
70	    setSalvando(true);
71	    setErro(null);
72	    try {
73	      const body = {
74	        name: form.name.trim(),
75	        slug: form.slug.trim(),
76	        descricao: form.descricao.trim() || null,
77	        is_auto: form.is_auto,
78	        ordem: Number(form.ordem) || 0,
79	      };
80	      if (isEdicao) {
81	        await atualizarTag(tag.id, { ...body, ativo: form.ativo });
82	      } else {
83	        await criarTag(body);
84	      }
85	      onSave();
86	    } catch (err) {
87	      setErro(err.message);
88	    } finally {
89	      setSalvando(false);
90	    }
91	  };
92	
93	  return (
94	    <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4" onClick={onClose}>
95	      <div className="bg-white dark:bg-zinc-800 rounded-2xl w-full max-w-md p-6" onClick={(e) => e.stopPropagation()}>
96	        <h3 className="text-lg font-bold text-gray-900 dark:text-zinc-100 mb-5">
97	          {isEdicao ? 'Editar Tag' : 'Nova Tag'}
98	        </h3>
99	
100	        <form onSubmit={handleSubmit} className="space-y-4">
101	          <div>
102	            <label className="block text-sm font-semibold text-gray-700 dark:text-zinc-300 mb-1">Nome *</label>
103	            <input required value={form.name} onChange={(e) => set('name', e.target.value)}
104	              className="w-full border border-gray-300 dark:border-zinc-700 bg-white dark:bg-zinc-900 text-gray-900 dark:text-zinc-100 rounded-xl px-3 py-2.5 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500"
105	              placeholder="Ex: Em Promoção" />
106	          </div>
107	
108	          <div>
109	            <label className="block text-sm font-semibold text-gray-700 dark:text-zinc-300 mb-1">Slug *</label>
110	            <input required value={form.slug} onChange={(e) => set('slug', e.target.value)}
111	              disabled={isEdicao}
112	              className="w-full border border-gray-300 dark:border-zinc-700 bg-white dark:bg-zinc-900 text-gray-900 dark:text-zinc-100 rounded-xl px-3 py-2.5 text-sm font-mono focus:outline-none focus:ring-2 focus:ring-blue-500 disabled:bg-gray-50 dark:disabled:bg-zinc-800 disabled:text-gray-400 dark:disabled:text-zinc-500"
113	              placeholder="em_promocao" />
114	            {!isEdicao && (
115	              <p className="text-xs text-gray-400 dark:text-zinc-500 mt-1">
116	                Identificador único. Não pode ser alterado depois de criado.
117	              </p>
118	            )}
119	          </div>
120	
121	          <div>
122	            <label className="block text-sm font-semibold text-gray-700 dark:text-zinc-300 mb-1">Descrição</label>
123	            <input value={form.descricao} onChange={(e) => set('descricao', e.target.value)}
124	              className="w-full border border-gray-300 dark:border-zinc-700 bg-white dark:bg-zinc-900 text-gray-900 dark:text-zinc-100 rounded-xl px-3 py-2.5 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500"
125	              placeholder="Breve descrição do carrossel" />
126	          </div>
127	
128	          <div className="grid grid-cols-2 gap-4">
129	            <div>
130	              <label className="block text-sm font-semibold text-gray-700 dark:text-zinc-300 mb-1">Ordem</label>
131	              <input type="number" min="0" value={form.ordem} onChange={(e) => set('ordem', e.target.value)}
132	                className="w-full border border-gray-300 dark:border-zinc-700 bg-white dark:bg-zinc-900 text-gray-900 dark:text-zinc-100 rounded-xl px-3 py-2.5 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500" />
133	            </div>
134	            <div className="flex flex-col gap-2 pt-6">
135	              <label className="flex items-center gap-2 cursor-pointer select-none">
136	                <input type="checkbox" checked={form.is_auto} onChange={(e) => set('is_auto', e.target.checked)}
137	                  disabled={isEdicao}
138	                  className="w-4 h-4 rounded accent-blue-600" />
139	                <span className="text-sm text-gray-700 dark:text-zinc-300">Automático</span>
140	              </label>
141	              {isEdicao && (
142	                <label className="flex items-center gap-2 cursor-pointer select-none">
143	                  <input type="checkbox" checked={form.ativo} onChange={(e) => set('ativo', e.target.checked)}
144	                    className="w-4 h-4 rounded accent-blue-600" />
145	                  <span className="text-sm text-gray-700 dark:text-zinc-300">Ativo</span>
146	                </label>
147	              )}
148	            </div>
149	          </div>
150	
151	          {form.is_auto && (
152	            <p className="text-xs text-amber-600 dark:text-amber-400 bg-amber-50 dark:bg-amber-950/30 rounded-lg px-3 py-2">
153	              Tags automáticas são calculadas pelo sistema (ex: mais vendidos por volume de vendas). O restaurante não pode atribuir manualmente.
154	            </p>
155	          )}
156	
157	          {erro && <p className="text-sm text-red-600 dark:text-red-400 bg-red-50 dark:bg-red-950/30 rounded-lg px-3 py-2">{erro}</p>}
158	
159	          <div className="flex gap-3 pt-1">
160	            <button type="button" onClick={onClose}
161	              className="flex-1 py-2.5 border border-gray-300 dark:border-zinc-700 rounded-xl text-sm text-gray-700 dark:text-zinc-300 hover:bg-gray-50 dark:hover:bg-zinc-700/40">
162	              Cancelar
163	            </button>
164	            <button type="submit" disabled={salvando}
165	              className="flex-1 py-2.5 bg-blue-600 text-white rounded-xl text-sm font-semibold hover:bg-blue-700 disabled:opacity-50">
166	              {salvando ? 'Salvando...' : 'Salvar'}
167	            </button>
168	          </div>
169	        </form>
170	      </div>
171	    </div>
172	  );
173	};
