175	const AdminTags = () => {
176	  const [tags, setTags] = useState([]);
177	  const [loading, setLoading] = useState(true);
178	  const [erro, setErro] = useState(null);
179	  const [modal, setModal] = useState(null); // null | 'nova' | tag_obj
180	  const [removendo, setRemovendo] = useState(null);
181	
182	  const carregar = useCallback(() => {
183	    setLoading(true);
184	    getTags()
185	      .then((d) => setTags(d.tags ?? []))
186	      .catch((e) => setErro(e.message))
187	      .finally(() => setLoading(false));
188	  }, []);
189	
190	  useEffect(() => { carregar(); }, [carregar]);
191	
192	  const handleToggle = async (tag) => {
193	    try {
194	      await atualizarTag(tag.id, { ativo: !tag.ativo });
195	      setTags((prev) => prev.map((t) => t.id === tag.id ? { ...t, ativo: !t.ativo } : t));
196	    } catch (e) {
197	      alert(e.message);
198	    }
199	  };
200	
201	  const handleRemover = async (tag) => {
202	    if (!window.confirm(`Remover a tag "${tag.name}"? O carrossel correspondente deixará de aparecer no catálogo.`)) return;
203	    setRemovendo(tag.id);
204	    try {
205	      await removerTag(tag.id);
206	      setTags((prev) => prev.filter((t) => t.id !== tag.id));
207	    } catch (e) {
208	      alert(e.message);
209	    } finally {
210	      setRemovendo(null);
211	    }
212	  };
213	
214	  return (
215	    <div className="min-h-screen bg-gray-50 dark:bg-zinc-900">
216	      <header className="bg-white dark:bg-zinc-800 border-b border-gray-200 dark:border-zinc-700 px-6 py-4 flex items-center justify-between flex-wrap gap-3">
217	        <div>
218	          <h1 className="text-xl font-bold text-gray-900 dark:text-zinc-100">Tags do Catálogo</h1>
219	          <p className="text-sm text-gray-500 dark:text-zinc-400">Cada tag ativa gera um carrossel no catálogo do restaurante</p>
220	        </div>
221	        <AdminNav active="/admin/tags" />
222	      </header>
223	
224	      <main className="p-6 max-w-4xl mx-auto">
225	        <div className="flex items-center justify-between mb-6">
226	          <p className="text-sm text-gray-500 dark:text-zinc-400">{tags.length} tag(s)</p>
227	          <button onClick={() => setModal('nova')}
228	            className="px-4 py-2 bg-blue-600 text-white text-sm font-semibold rounded-xl hover:bg-blue-700 flex items-center gap-2">
229	            <Icon name="Plus" size={16} /> Nova Tag
230	          </button>
231	        </div>
232	
233	        {erro && <p className="text-red-600 dark:text-red-400 text-sm mb-4 bg-red-50 dark:bg-red-950/30 rounded-lg px-4 py-3">{erro}</p>}
234	
235	        {loading ? (
236	          <div className="flex justify-center py-16">
237	            <div className="w-8 h-8 border-4 border-blue-600 border-t-transparent rounded-full animate-spin" />
238	          </div>
239	        ) : tags.length === 0 ? (
240	          <div className="bg-white dark:bg-zinc-800 rounded-2xl border border-gray-200 dark:border-zinc-700 p-14 text-center">
241	            <Icon name="Tag" size={44} className="text-gray-200 dark:text-zinc-600 mx-auto mb-3" />
242	            <p className="text-gray-400 dark:text-zinc-500 mb-4">Nenhuma tag cadastrada</p>
243	            <button onClick={() => setModal('nova')}
244	              className="px-5 py-2.5 bg-blue-600 text-white text-sm font-semibold rounded-xl hover:bg-blue-700">
245	              Criar primeira tag
246	            </button>
247	          </div>
248	        ) : (
249	          <div className="space-y-3">
250	            <AnimatePresence>
251	              {[...tags].sort((a, b) => a.ordem - b.ordem || a.name.localeCompare(b.name)).map((tag) => (
252	                <motion.div key={tag.id}
253	                  initial={{ opacity: 0, y: 8 }}
254	                  animate={{ opacity: 1, y: 0 }}
255	                  exit={{ opacity: 0, y: -8 }}
256	                  className={`bg-white dark:bg-zinc-800 rounded-2xl border px-5 py-4 flex items-center gap-4 group transition-all ${
257	                    tag.ativo ? 'border-gray-100 dark:border-zinc-700 hover:shadow-md' : 'border-dashed border-gray-200 dark:border-zinc-700 opacity-60'
258	                  }`}
259	                >
260	                  {/* Ordem */}
261	                  <span className="w-8 h-8 rounded-lg bg-gray-100 dark:bg-zinc-700 flex items-center justify-center text-xs font-bold text-gray-500 dark:text-zinc-400 flex-shrink-0">
262	                    {tag.ordem}
263	                  </span>
